Value.Code:
Task justCompleted = agent.currentTask;
if (agent.currentTask == Task.LOAD && agent.currentLoadingPoint != null) {
    agent.currentLoadingPoint.amount -= agent.currentLoadingPoint.loadAmount;
}
TaskEvent completionEvent = agent.currentTask == Task.LOAD ? TaskEvent.LOAD_COMPLETE : TaskEvent.DUMP_COMPLETE;
agent.currentTask = nextTask(completionEvent, shiftActive);
logger.info("Truck finished {}, task now: {}", justCompleted == Task.LOAD ? "loading" : "dumping", agent.currentTask);

TaskEvent arrivalEvent =
    agent.currentTask == Task.TO_LOAD ? TaskEvent.LOADING_ARRIVAL :
    agent.currentTask == Task.TO_DUMP ? TaskEvent.DUMPING_ARRIVAL :
    TaskEvent.HOME_ARRIVAL;
Task result = nextTask(arrivalEvent, shiftActive);
agent.currentTask = result;
logger.info("Truck arrived, task now: {}", agent.currentTask);

if (agent.currentLoadingPoint != null && agent.currentLoadingPoint.pool != null) {
    return new ResourcePool[][]{ { agent.currentLoadingPoint.pool } };
}
return new ResourcePool[0][];

if (agent.currentLoadingPoint != null) {
    logger.info("Truck seized loading point: {}", agent.currentLoadingPoint.id);
}

if (agent.currentTask == Task.TO_LOAD && agent.currentLoadingPoint != null) {
    logger.info("Truck seized loading point: {}", agent.currentLoadingPoint.id);
} else if (agent.currentTask == Task.TO_DUMP && agent.currentDumpingPoint != null) {
    logger.info("Truck seized dumping point: {}", agent.currentDumpingPoint.id);
}

if (agent.currentTask == Task.WAIT_AT_HOME) {
    logger.info("Truck parked at home for shift break");
}

for (DumpingPoint dp : p_dumpingPoints) {
    if (dp.pool != null && !agent.resourceUnitsOfPool(dp.pool).isEmpty()) {
        agent.currentDumpingPoint = dp;
        logger.info("Truck seized dumping point: {}", dp.id);
        break;
    }
}
